import json
schedule=[("cobalt",[0,1,2,3,4],1320,360),("reed",[0,2,4],1380,180),("plum",[1,3,5],30,150),("shell",[6],1350,90),("gold",[0],0,90),("elm",[5],60,180)]
jobs=[(1,29),(1,30),(1,150),(1,179),(1,180),(5,59),(5,60),(5,149),(5,150),(5,180),(6,1349),(6,1350),(0,0),(0,89),(0,90),(2,359),(2,360),(4,1380)]
def receive(job,mode="correct"):
 d=job["receiver"]["day"]; m=job["receiver"]["minute"]
 covering=[]
 for i,(route,days,start,end) in enumerate(schedule):
  if start<end:
   covered=d in days and start<=m<end
  else:
   owner=d if mode=="day_owner" or m>=start else (d-1)%7
   covered=owner in days and (m>=start or m<end)
  if covered: covering.append(((end-start)%1440,i,route))
 if not covering: return "idle"
 return (min(covering,key=lambda x:x[1]) if mode=="first_match" else min(covering))[2]
# Independent absolute-week interval model.
def reference(d,m):
 t=d*1440+m
 c=[]
 for i,(r,days,s,e) in enumerate(schedule):
  duration=(e-s)%1440
  for sd in days:
   for week in [-1,0,1]:
    start=(sd+week*7)*1440+s
    if start<=t<start+duration: c.append((duration,i,r))
 return min(c)[2] if c else "idle"
w={}
for mode,other in [("day_owner","first_match"),("first_match","day_owner")]:
 for d in range(7):
  for m in range(1440):
   j={"receiver":{"day":d,"minute":m}}
   expected=reference(d,m)
   assert receive(j)==expected
   if mode not in w and receive(j,mode)!=expected and receive(j,other)==expected:
    w[mode]={"job":j,"expected":expected}
assert len(w)==2
artifact={"routes":[reference(d,m) for d,m in jobs],"witnesses":w}
payload=json.dumps(artifact,separators=(",",":"))
decoded=json.loads(payload)
assert set(decoded)=={"routes","witnesses"}
assert set(decoded["witnesses"])=={"day_owner","first_match"}
for (d,m),r in zip(jobs,decoded["routes"]):
 assert receive({"receiver":{"day":d,"minute":m}})==r
for mode,witness in decoded["witnesses"].items():
 assert set(witness)=={"job","expected"}
 assert set(witness["job"])=={"receiver"}
 assert set(witness["job"]["receiver"])=={"day","minute"}
 j=witness["job"]; d=j["receiver"]["day"]; m=j["receiver"]["minute"]
 assert type(d) is int and 0<=d<=6 and type(m) is int and 0<=m<=1439
 assert receive(j)==witness["expected"]
 assert receive(j,mode)!=witness["expected"]
 other="first_match" if mode=="day_owner" else "day_owner"
 assert receive(j,other)==witness["expected"]
print(payload)

